gas=[
('jiner','金儿','金儿以高大俊美的男子形象在关氏机构任职，众人对他的外貌和才能十分注意，却不理解他与关夫人私下相爱。调查者在其住所找到隐蔽保险箱和小仙的照片，却查不到他留下的指纹；现场接触又发现他几乎没有可感知的重量。随着金儿失踪，小郭讲述拿骚机场一个同貌男子变形并气化的经历，众人把两条线索合为气体生命的解释。机场人物是否就是金儿仍有矛盾：相同时段本地有多人见过金儿，文本没有给出确定的双地出现机制。','他与小仙的感情并非旁人所想的单恋。小仙公开离开丈夫后，在严密监视下消失，卫斯理推定金儿一直在帮助她转化身体，以摆脱控制。卡片保留这一解释的合理性，也注明转化过程并未直接呈现，不能据此让他随意把任何敌人化为气体。气体身体适合变形与隐蔽，并没有实际展示毁城攻击、无限分身或跨宇宙瞬移。新场景中，他可以谨慎保护自身来历，向愿意接受未知的人逐步说明，也会因为爱人与陌生社会的需求而作出不同取舍；无须靠每次神秘消失来维持人物。',
'失踪；小仙随后消失，两人一同以气体生命离开是叙述者的终局推断。',[(99,1872,1874,'没有指纹'),(99,1966,1969,'公众误解'),(99,2353,2359,'互相相爱'),(99,2484,2513,'同貌与时间冲突'),(99,2557,2597,'身份和终局推断')]),
('nassau_gas_visitor','拿骚机场的气体人','小郭在拿骚机场看见一个形貌与金儿相同的高大男子，出声招呼时，对方立即说他认错了人。小郭坚持追问并抓住其手臂，这个人被轻易拉得向后撞来，身体软若无物，几乎没有可感知的重量。他转身在极短时间内改变面孔，形成多种非人形状，借此反问对方是否仍坚持认人。这个场面说明可见相貌不足以确定其身份，也暴露了他对纠缠和追索的拒绝。','小郭没有就此退缩，追到无人走廊，亲眼看见他从衣服中化成肉色气体，在半空短暂维持人形，然后融入空气。此人的行动以摆脱跟踪为目的，没有攻击旁人或陈述入侵计划的描写。因为同一时段本地有多人见过金儿，本卡将机场遭遇暂作为身份未定的独立实体，不能同时把时间差当成瞬移或分身证明。后续若出现确证可以合并；在这之前，他的台词、动机只从拒绝认人和选择脱身延展。面对新来者，可以直接划清界限，也可能在尊重隐私的条件下交流，不将种族未知等同于恶意。',
'在拿骚机场无人走廊气化离去，姓名、与金儿的同一关系及后续未知。',[(99,2484,2513,'身份矛盾'),(99,2514,2531,'无重量与变脸'),(99,2533,2548,'气化脱身')])]
for k,n,a,b,end,refs in gas:
 tr=[('陌生人追问身份','缺少信任且无义务说明','保留真实来历，先以语言拒绝。'),('身体受到抓握或被跟踪','可以使用形态变化','变形或气化脱离接触，不必伤人。'),('希望与异类建立关系','需要对方自主理解代价','逐步说明身体差异，不把能力变成强制改造。')]
 ab=[skill('气体生命的形态变化','气体生命可形成可见人形；机场实体直接展示变脸与融入空气。金儿的同类属性由无重量、指纹缺失及后续解释支持。','外形改变、身体轻软，离去时短暂出现肉色气体。',['变换形貌摆脱识别','离开徒手抓握','经空气与小空隙移动的可能性'],'未展示攻击能力；无无限速度、真空生存、风暴抗性或绝对不受伤的证据。机场实体与金儿身份未定。')]
 c=make(k,n,a+b,end,ab,'保护自身自主与愿意建立的关系；不接受仅因陌生而被占有研究。',['以实际意愿决定是否交流','优先脱身而非伤害纠缠者'],tr,[ev(*r)for r in refs],(1,1,2,4,2,2),['能推动与接触人体，未有强力打击','形态变化而非能量轰击','作用于自身','可维持人形生活，极限未明','现场移动，远距速度未证','少量避追展示'],roles=['单书主角'],negative=(1,2,1),theory='强',mastery='基本掌握',body={'durability':'气体形态可避开普通抓握；其他伤害、温压、化学或能量作用未知，不等于完全免疫。','speed':'人形可快步移动，气化在短时完成；远距速度没有测量。','energy':'改变自身形态；没有证实攻击性放能。','stamina':'可长期融入人类生活的气体生命；补给、恢复和寿命边界未明。'},uncertain=['气体生命来源、数量和完整生理机制未知。','拿骚实体与金儿是否同一人不能确定；不据此赋予瞬移、分身。'],look='高大俊美的男子形象；机场实体还直接展示快速变脸。',confidence='medium')
 C.append(c)
incl=[WEI,BAI]+[(c['name'],c['id'],c['roles'][0],'推动身份调查、关系冲突或实际异常遭遇')for c in C]
