save('part_b',C,[cov(99,incl,[('关氏职员、助手、保安与警方人员','无独立角色线的一次性工作人员；不为每名围观者建卡。'),('太上老君、三清、瓶中巨人','仅为温宝裕的神话类比，并未在故事中登场。')],['李远的谋杀故事明确属妄想，不能用作关总裁或金儿的确定战绩。','同貌与异地时间冲突尚未解释，机场气体人暂建身份未定卡；小仙气化为有依据的终局推断。'])])
